// DirectoryServiceServer is the server API for DirectoryService service.
// All implementations must embed UnimplementedDirectoryServiceServer
// for forward compatibility.
//
// DirectoryService owns departments and employees.
type DirectoryServiceServer interface {
	CreateDepartment(context.Context, *CreateDepartmentRequest) (*CreateDepartmentResponse, error)
	ListDepartments(context.Context, *ListDepartmentsRequest) (*ListDepartmentsResponse, error)
	UpdateDepartment(context.Context, *UpdateDepartmentRequest) (*UpdateDepartmentResponse, error)
	CreateEmployee(context.Context, *CreateEmployeeRequest) (*CreateEmployeeResponse, error)
	GetEmployee(context.Context, *GetEmployeeRequest) (*GetEmployeeResponse, error)
	ListEmployees(context.Context, *ListEmployeesRequest) (*ListEmployeesResponse, error)
	UpdateEmployee(context.Context, *UpdateEmployeeRequest) (*UpdateEmployeeResponse, error)
	DeactivateEmployee(context.Context, *DeactivateEmployeeRequest) (*DeactivateEmployeeResponse, error)
	// ActivateEmployee reinstates someone marked as left - people come
	// back, and a mistaken departure must be undoable from the UI.
	ActivateEmployee(context.Context, *ActivateEmployeeRequest) (*ActivateEmployeeResponse, error)
	// OpenAccount gives an existing employee a login; employees created
	// without one are the normal case (not everyone uses the system).
	OpenAccount(context.Context, *OpenAccountRequest) (*OpenAccountResponse, error)
	// ResetPassword is the administrator path: no old password, but it needs
	// iam:employee:write, which the gateway enforces.
	ResetPassword(context.Context, *ResetPasswordRequest) (*ResetPasswordResponse, error)
	// ChangePassword is the self-service path: the caller's own account,
	// proven with the current password.
	ChangePassword(context.Context, *ChangePasswordRequest) (*ChangePasswordResponse, error)
	// ListManagers returns an employee's direct manager, for approval flows
	// whose node says "whoever the submitter reports to" rather than naming a
	// role. A list because the caller wants assignees either way, and someone
	// at the top of the tree simply has none.
	ListManagers(context.Context, *ListManagersRequest) (*ListManagersResponse, error)
	// SetManager changes who someone reports to.
	SetManager(context.Context, *SetManagerRequest) (*SetManagerResponse, error)
	// InviteEmployee mints a one-time activation link. It does not send it:
	// every mail this system emits leaves through some employee's own bound
	// mailbox, and iam has no mail client — the mail service already depends on
	// iam, so the reverse edge would close a cycle. The gateway, which holds
	// both, does the sending.
	InviteEmployee(context.Context, *InviteEmployeeRequest) (*InviteEmployeeResponse, error)
	// CreatePasswordReset is the administrator's version of the login page's
	// 忘记密码: same link, but minted on somebody's behalf and recorded as such.
	CreatePasswordReset(context.Context, *CreatePasswordResetRequest) (*CreatePasswordResetResponse, error)
	// RecordAccountEvent writes an account action into the change history when
	// the action itself happens outside iam — today, the gateway ending
	// somebody's sessions in Redis. Audit lives here because 变更记录 lives here.
	RecordAccountEvent(context.Context, *RecordAccountEventRequest) (*RecordAccountEventResponse, error)
	// ImportEmployees takes a whole pasted block. dry_run makes it a preview:
	// same validation, nothing written. The two share one code path on purpose
	// — a preview computed by a second, simpler validator eventually lies, and
	// it lies at the moment somebody has already decided to trust it.
	ImportEmployees(context.Context, *ImportEmployeesRequest) (*ImportEmployeesResponse, error)
	ListDirectoryChanges(context.Context, *ListDirectoryChangesRequest) (*ListDirectoryChangesResponse, error)
	mustEmbedUnimplementedDirectoryServiceServer()
}

