// AccessServiceServer is the server API for AccessService service.
// All implementations must embed UnimplementedAccessServiceServer
// for forward compatibility.
type AccessServiceServer interface {
	CreateRole(context.Context, *CreateRoleRequest) (*CreateRoleResponse, error)
	ListRoles(context.Context, *ListRolesRequest) (*ListRolesResponse, error)
	// 角色管理页用：含停用的，否则停掉之后没有入口能把它启用回来。
	ListAllRoles(context.Context, *ListAllRolesRequest) (*ListAllRolesResponse, error)
	// 停用/启用。角色只停用不真删——编号被员工、权限、数据范围和审批节点
	// 引用着，真删会让审批流指向不存在的东西且无从追溯。停用是真收权。
	SetRoleStatus(context.Context, *SetRoleStatusRequest) (*SetRoleStatusResponse, error)
	GrantRolePermissions(context.Context, *GrantRolePermissionsRequest) (*GrantRolePermissionsResponse, error)
	AssignEmployeeRoles(context.Context, *AssignEmployeeRolesRequest) (*AssignEmployeeRolesResponse, error)
	ListPermissions(context.Context, *ListPermissionsRequest) (*ListPermissionsResponse, error)
	// CheckPermission answers "may employee X do Y", used by the gateway on
	// every mutating request.
	CheckPermission(context.Context, *CheckPermissionRequest) (*CheckPermissionResponse, error)
	// ListEmployeePermissions returns every permission code an employee holds,
	// used by the gateway to render menus and by the frontend to hide actions.
	ListEmployeePermissions(context.Context, *ListEmployeePermissionsRequest) (*ListEmployeePermissionsResponse, error)
	// ListRoleMembers returns the active employees holding a role. The approval
	// engine calls it when a flow node names a role rather than a person, to
	// turn that node into concrete tasks.
	ListRoleMembers(context.Context, *ListRoleMembersRequest) (*ListRoleMembersResponse, error)
	// VisibleEmployees answers "whose documents may this person see" for one
	// module, from the data scope attached to their roles. Business services
	// ask it instead of inventing their own idea of who owns what.
	VisibleEmployees(context.Context, *VisibleEmployeesRequest) (*VisibleEmployeesResponse, error)
	// ListDataScopes returns every role's data scope, for the admin screen.
	ListDataScopes(context.Context, *ListDataScopesRequest) (*ListDataScopesResponse, error)
	// SetDataScope changes one role's scope for one module.
	SetDataScope(context.Context, *SetDataScopeRequest) (*SetDataScopeResponse, error)
	mustEmbedUnimplementedAccessServiceServer()
}

